<script setup lang="ts">
import { onMounted } from 'vue'; import { RouterLink } from 'vue-router'; import { useBookingStore } from '@/stores/booking'
const store=useBookingStore(); const money=(v:number)=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(v); const image=(index:number)=>store.courts[index]?.image_url||`/aura/court-${index+4}.jpg`; onMounted(async()=>{try{await store.loadCourts()}catch{ /* store exposes the error */ }})
</script>
<template><section class="page-shell"><div class="eyebrow">Tìm sân phù hợp</div><h1 class="page-title">Danh sách sân</h1><p class="muted" style="max-width:560px">Những không gian được tuyển chọn để mỗi trận đấu có cảm giác thật đúng nhịp.</p><p v-if="store.error" class="error">{{ store.error }}</p><div class="court-grid" style="margin-top:38px"><RouterLink v-for="(court,index) in store.courts" :key="court.id" :to="`/courts/${court.id}`" class="court-card"><div class="court-card-image"><img :src="image(index)" :alt="court.name"/><span class="tag">Từ {{money(court.price_slots?.[0]?.price||120000)}}/giờ</span></div><div class="court-info"><h3>{{court.name}}</h3><p class="muted">{{court.description||'Câu lạc bộ Aura Court'}} · <span class="badge">Đang mở</span></p></div></RouterLink></div></section></template>
